#include "stm32g4xx.h"

int main(void)
{
    /* 1. Enable peripheral clocks for GPIOA (AHB2) and TIM1 (APB2) */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 2. Configure PA8 for Alternate Function 6 (TIM1_CH1) */
    GPIOA->MODER &= ~GPIO_MODER_MODE8_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos);       /* Alternate function mode (10b) */

    GPIOA->AFR[1] &= ~GPIO_AFRH_AFSEL8_Msk;
    GPIOA->AFR[1] |= (6U << GPIO_AFRH_AFSEL8_Pos);      /* AF6 = TIM1_CH1 */

    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos); /* Very high speed (11b) */

    /* 3. Configure TIM1 time-base:
     *    TIM1 clock = PCLK2 = 170 MHz (APB2 prescaler = 1).
     *    Target PWM freq = 20 kHz -> Counter period = 170 MHz / 20 kHz = 8500 counts.
     *    PSC = 0, ARR = 8500 - 1 = 8499.
     */
    TIM1->PSC = 0;
    TIM1->ARR = 8499;

    /* 4. Configure 25% duty cycle:
     *    CCR1 = 8500 * 0.25 = 2125 counts.
     */
    TIM1->CCR1 = 2125;

    /* 5. Configure Channel 1:
     *    - CC1S = 00 (Output)
     *    - OC1M = 0110 (PWM Mode 1: active while CNT < CCR1)
     *    - OC1PE = 1 (Preload enable)
     */
    TIM1->CCMR1 &= ~(TIM_CCMR1_CC1S_Msk | TIM_CCMR1_OC1M_Msk);
    TIM1->CCMR1 |= (TIM_CCMR1_OC1M_1 | TIM_CCMR1_OC1M_2) | TIM_CCMR1_OC1PE;

    /* 6. Configure Channel 1 output: active-high polarity (CC1P = 0) and enable (CC1E = 1) */
    TIM1->CCER &= ~TIM_CCER_CC1P;
    TIM1->CCER |= TIM_CCER_CC1E;

    /* 7. Enable Auto-Reload Preload (ARPE) and Main Output Enable (MOE for advanced timers) */
    TIM1->CR1 |= TIM_CR1_ARPE;
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* 8. Trigger update event to initialize shadow registers, then start counter */
    TIM1->EGR |= TIM_EGR_UG;
    TIM1->CR1 |= TIM_CR1_CEN;

    while (1)
    {
    }
}
```

### Explanation

1. **Clock & Routing**: Pin PA8 is configured in alternate function mode to AF6 (`TIM1_CH1`). Clocks for `GPIOA` on AHB2 and `TIM1` on APB2 are enabled via the RCC registers.
2. **Timing Calculation**: Since the APB2 prescaler is 1, TIM1 receives the full 170 MHz SYSCLK. With `PSC = 0`, each tick is $\approx 5.88\text{ ns}$. An `ARR` value of `8499` gives an 8500-count period:
   $$\frac{170\text{ MHz}}{8500} = 20\text{ kHz (0 \% error)}$$
3. **Duty Cycle**: In PWM Mode 1 with upcounting, the channel output remains high while `TIM1_CNT < TIM1_CCR1`. Setting `CCR1 = 2125` yields:
   $$\frac{2125}{8500} = 25.0\text{ \% duty cycle (0 percentage point error)}$$
4. **Advanced Timer Requirement**: TIM1 is an advanced-control timer; setting `TIM1->BDTR |= TIM_BDTR_MOE` (Main Output Enable) is mandatory to drive the output signal onto the external pin.

